#include <iostream>
struct X {
    int data = 10;  // Member variable
};
void g(X* p) {
    if (p != nullptr) {  // Runtime check to avoid dereference issues
        std::cout << p->data << std::endl;  // Dereferences pointer
    } else {
        std::cout << "Null pointer" << std::endl;
    }
}
int main() {
    X obj;  // Stack-allocated object
    g(&obj);  // Passes address of obj as a pointer
    X* ptr = new X();  // Dynamically allocated
    g(ptr);  // Passes the pointer value
    delete ptr;  // Manual memory management
    return 0;
}
